import random
from itertools import chain
from typing import Union, List

from rdkit import DataStructs, Chem
from rdkit.Chem import Mol, rdmolfiles, rdmolops, MolFromSmiles, MolToSmiles
from rdkit.Chem.rdChemReactions import ChemicalReaction


class ChemUtils:
    """
    ChemUtils class contains a set of chemical utilities.
    """

    # maximum number of products generated by a reaction (RDKit's default)
    MAX_PRODUCTS = 1000

    @staticmethod
    def _shuffle_atoms(mol: Mol):
        """
        Returns a copy of the molecule with the atoms in a random order.

        Parameters
        ----------
        mol: Mol
            RDKit Mol object

        Returns
        -------
        Mol:
            molecule with the atoms randomly renumbered
        """
        n_atoms = mol.GetNumAtoms()
        return rdmolops.RenumberAtoms(mol, random.sample(range(n_atoms), n_atoms))

    @staticmethod
    def canonicalize_atoms(mol: Mol):
        """
        Returns the canonical atom ranking for each atom of a molecule fragment.
        (see: https://www.rdkit.org/docs/source/rdkit.Chem.rdmolfiles.html#rdkit.Chem.rdmolfiles.CanonicalRankAtoms)
        Parameters
        ----------
        mol: Mol
            RDKit Mol object

        Returns
        -------
        Mol:
            canonical mol
        """
        try:
            new_order = rdmolfiles.CanonicalRankAtoms(mol)
            mol = rdmolops.RenumberAtoms(mol, new_order)
            return mol
        except Exception:
            return mol

    @staticmethod
    def react(mol: Union[Mol, List[Mol]], rule: ChemicalReaction):
        """
        Apply the reaction to a sequence of reactant molecules and return the products as a tuple of tuples.
        (see: https://www.rdkit.org/docs/source/rdkit.Chem.rdChemReactions.html#rdkit.Chem.rdChemReactions.ChemicalReaction.RunReactants )
        Parameters
        ----------
        mol: Union[Mol, List[Mol]]
            RDKit Mol or list of Mol objects
        rule: ChemicalReaction
            RDKit ChemicalReaction object

        Returns
        -------
        List[str]:
            list of products SMILES
        """
        try:
            reactants = tuple(mol) if isinstance(mol, list) else (mol,)
            products = rule.RunReactants(reactants, ChemUtils.MAX_PRODUCTS)
            if len(products) >= ChemUtils.MAX_PRODUCTS:
                # RDKit stops after MAX_PRODUCTS matches, which are always found in the first atoms of the reactants;
                # renumbering the atoms randomly makes the products kept a random sample of all the possible ones
                reactants = tuple(ChemUtils._shuffle_atoms(reactant) for reactant in reactants)
                products = rule.RunReactants(reactants, ChemUtils.MAX_PRODUCTS)
            return list(set([MolToSmiles(s) for s in list(chain.from_iterable(products))]))
        except Exception:
            return ()

    @staticmethod
    def valid_product(smiles: str):
        """
        Returns True if the SMILES string is a valid reaction product.

        Parameters
        ----------
        smiles: str
            SMILES string
        Returns
        -------
        bool:
            True if the SMILES string is a valid product
        """
        if '*' in smiles:
            return False
        mol = MolFromSmiles(smiles, sanitize=False)
        if mol is None:
            return False
        try:
            Chem.SanitizeMol(mol)
        except:
            return False
        if mol.GetNumAtoms() < 4:
            return False
        carbon = MolFromSmiles('C')
        if not mol.HasSubstructMatch(carbon):
            return False
        return True

    @staticmethod
    def _rdkit_fingerprint(mol: Mol):
        """
        Computes the RDKit fingerprint of a molecule.
        Same arguments as the default of the deprecated rdkit.Chem.Fingerprints.FingerprintMols.FingerprintMol.

        Parameters
        ----------
        mol: Mol
            The molecule.
        Returns
        -------
        ExplicitBitVect
            The fingerprint of the molecule.
        """
        return Chem.RDKFingerprint(mol, minPath=1, maxPath=7, fpSize=2048, nBitsPerHash=2, useHs=False,
                                   tgtDensity=0.3, minSize=64)

    @staticmethod
    def calc_fingerprint_similarity(smiles1: str, smiles2: str):
        """
        Calculates the similarity between two molecules based on fingerprints.

        Parameters
        ----------
        smiles1: str
            The first molecule smiles.
        smiles2: str
            The second molecule smiles.
        Returns
        -------
        float
            The similarity between the two molecules.
        """
        mol1 = MolFromSmiles(smiles1)
        mol2 = MolFromSmiles(smiles2)
        if mol1 and mol2:
            fp1 = ChemUtils._rdkit_fingerprint(mol1)
            fp2 = ChemUtils._rdkit_fingerprint(mol2)
            return DataStructs.FingerprintSimilarity(fp1, fp2)
        return 0.0

    @staticmethod
    def most_similar_compound(smiles: str, smiles_list: List[str], tolerance: float = 0.25):
        """
        Finds the most similar compound in a list of compounds.

        Parameters
        ----------
        smiles: str
            The smiles of the compound to find the most similar compound for.
        smiles_list: List[str]
            The list of compounds to find the most similar compound in.
        tolerance: float
            Compounds between max_similarity and max_similarity - tolerance are considered to be picked.

        Returns
        -------
        str
            The most similar compound SMILES string.
        """
        if len(smiles_list) == 1:
            return smiles_list[0]
        sims = [ChemUtils.calc_fingerprint_similarity(smiles, s) for s in smiles_list]
        idx = [i for i, x in enumerate(sims) if x >= max(sims) - tolerance]
        return smiles_list[random.choice(idx)]

    @staticmethod
    def canonicalize_smiles(smiles: str, include_stereocenters=True):
        """
        Returns the canonical SMILES string.

        Parameters
        ----------
        smiles: str
            SMILES string
        include_stereocenters: bool
            whether to keep the stereochemical information in the canonical SMILES string.

        Returns
        -------
        str:
            canonical SMILES string
        """
        mol = MolFromSmiles(smiles)
        if mol is None:
            return smiles
        return MolToSmiles(mol, isomericSmiles=include_stereocenters)
